//! Windowed notes — folders sidebar, note list, editor. `run()`
//! (generated by `libra::app!`) watches the view file in debug builds,
//! so editing notes.lx hot-reloads with your notes preserved.

fn main() {
    if let Err(e) = notes::run() {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}
